 38	aisoc_dds_status_t aisoc_dds_publisher_create(
 39	    aisoc_dds_participant_t *part,
 40	    const aisoc_dds_publisher_config_t *config,
 41	    aisoc_dds_publisher_t **out_pub
 42	) {
 43	    if (part == nullptr || config == nullptr || out_pub == nullptr) {
 44	        return AISOC_DDS_ERR_NULL_PTR;
 45	    }
 46	    if (config->topic_name == nullptr) {
 47	        return AISOC_DDS_ERR_INVALID_PARAM;
 48	    }
 49	    *out_pub = nullptr;
 50	
 51	    if (!reserve_publisher_quota()) {
 52	        return AISOC_DDS_ERR_RESOURCE_LIMIT;
 53	    }
 54	
 55	    std::lock_guard<std::mutex> lock(part->mutex);
 56	    eprosima::fastdds::dds::Topic* topic = resolve_topic(part->dds_participant, config->topic_name);
 57	    if (topic == nullptr) {
 58	        aisoc::dds::g_publisher_count.fetch_sub(1U);
 59	        return AISOC_DDS_ERR_PUB_FAILED;
 60	    }
 61	
 62	    aisoc_dds_publisher_t* pub = new aisoc_dds_publisher();
 63	    pub->parent = part;
 64	    pub->dds_topic = topic;
 65	    pub->topic_name = config->topic_name;
 66	    pub->matched_count.store(0U);
 67	    pub->listener = new aisoc::dds::AisocWriterListener(pub);
 68	
 69	    eprosima::fastdds::dds::DataWriterQos w_qos = eprosima::fastdds::dds::DATAWRITER_QOS_DEFAULT;
 70	    aisoc::dds::configure_writer_qos(config->topic_name, config->qos_profile, w_qos);
 71	
 72	    try {
 73	        pub->dds_writer = part->dds_publisher->create_datawriter(
 74	            topic, w_qos, pub->listener, eprosima::fastdds::dds::StatusMask::all()
 75	        );
 76	    } catch (...) {
 77	        pub->dds_writer = nullptr;
 78	    }
 79	    if (pub->dds_writer == nullptr) {
 80	        part->dds_participant->delete_topic(topic);
 81	        delete pub->listener;
 82	        delete pub;
 83	        aisoc::dds::g_publisher_count.fetch_sub(1U);
 84	        return AISOC_DDS_ERR_PUB_FAILED;
 85	    }
 86	
 87	    *out_pub = pub;
 88	    return AISOC_DDS_OK;
 89	}
