    if (getrusage(RUSAGE_SELF, &usage) == 0) {
        long user_ms = usage.ru_utime.tv_sec * 1000L + usage.ru_utime.tv_usec / 1000L;
        long sys_ms = usage.ru_stime.tv_sec * 1000L + usage.ru_stime.tv_usec / 1000L;
