static void run_single_publish_cycle(uint32_t domain_id, uint32_t seq) {
    aisoc_dds_participant_config_t cfg = {domain_id, "aisoc_restart_part", nullptr};
    aisoc_dds_participant_t* p = nullptr;
    assert(aisoc_dds_participant_create(&cfg, &p) == AISOC_DDS_OK);

    aisoc_dds_publisher_config_t pub_cfg;
    pub_cfg.topic_name = AISOC_TOPIC_RAW_TEMP;
    pub_cfg.qos_profile = AISOC_DDS_QOS_RELIABLE_VOLATILE;
    aisoc_dds_publisher_t* pub = nullptr;
    assert(aisoc_dds_publisher_create(p, &pub_cfg, &pub) == AISOC_DDS_OK);

    aisoc_raw_temp_t sample;
    init_sample_raw_temp(&sample, seq);
    assert(aisoc_dds_publish_raw_temp(pub, &sample) == AISOC_DDS_OK);

    aisoc_dds_publisher_destroy(pub);
    aisoc_dds_participant_destroy(p);
}

