static bool reserve_publisher_quota() {
    uint32_t current = aisoc::dds::g_publisher_count.load();
    while (current < AISOC_DDS_MAX_PUBLISHERS) {
        if (aisoc::dds::g_publisher_count.compare_exchange_weak(current, current + 1U)) {
            return true;
        }
    }
    return false;
}

aisoc_dds_status_t aisoc_dds_publisher_create(
    aisoc_dds_participant_t *part,
    const aisoc_dds_publisher_config_t *config,
    aisoc_dds_publisher_t **out_pub
) {
    if (part == nullptr || config == nullptr || out_pub == nullptr) {
        return AISOC_DDS_ERR_NULL_PTR;
    }
    if (config->topic_name == nullptr) {
        return AISOC_DDS_ERR_INVALID_PARAM;
    }
    *out_pub = nullptr;

    if (!reserve_publisher_quota()) {
        return AISOC_DDS_ERR_RESOURCE_LIMIT;
    }

    std::lock_guard<std::mutex> lock(part->mutex);
    eprosima::fastdds::dds::Topic* topic = resolve_topic(part->dds_participant, config->topic_name);
    if (topic == nullptr) {
        aisoc::dds::g_publisher_count.fetch_sub(1U);
        return AISOC_DDS_ERR_PUB_FAILED;
    }

    aisoc_dds_publisher_t* pub = new aisoc_dds_publisher();
    pub->parent = part;
    pub->dds_topic = topic;
    pub->topic_name = config->topic_name;
    pub->matched_count.store(0U);
    pub->listener = new aisoc::dds::AisocWriterListener(pub);

    eprosima::fastdds::dds::DataWriterQos w_qos = eprosima::fastdds::dds::DATAWRITER_QOS_DEFAULT;
    aisoc::dds::configure_writer_qos(config->topic_name, config->qos_profile, w_qos);

    try {
        pub->dds_writer = part->dds_publisher->create_datawriter(
            topic, w_qos, pub->listener, eprosima::fastdds::dds::StatusMask::all()
        );
    } catch (...) {
        pub->dds_writer = nullptr;
    }
    if (pub->dds_writer == nullptr) {
        part->dds_participant->delete_topic(topic);
        delete pub->listener;
        delete pub;
        aisoc::dds::g_publisher_count.fetch_sub(1U);
        return AISOC_DDS_ERR_PUB_FAILED;
    }

    *out_pub = pub;
    return AISOC_DDS_OK;
}

